<script setup lang="ts">import {computed,ref} from "vue";import {Check,X,Clock3} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import StatCard from "@/components/zs/StatCard.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import ZButton from "@/components/zs/ZButton.vue";import ConfirmDialog from "@/components/zs/ConfirmDialog.vue";import {useAsyncData} from "@/composables/useAsyncData";import {operationsRepository} from "@/services/operations/repository";import {useCompanyStore} from "@/stores/company";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";import type {Recommendation} from "@/types/operations";setPageMeta("AI Priorities","Review and approve AI-generated operational recommendations.");const c=useCompanyStore(),s=useAsyncData(()=>operationsRepository.recommendations(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),target=ref<Recommendation|null>(null),decision=ref<"approved"|"rejected">("approved"),rows=computed(()=>s.data.value??[]);function ask(x:Recommendation,d:"approved"|"rejected"){target.value=x;decision.value=d}async function decide(){if(!target.value)return;await operationsRepository.updateRecommendation(c.activeCompanyId,target.value.id,decision.value);showToast(decision.value==='approved'?'Recommendation approved':'Recommendation rejected','No task changes occur without your approval.');target.value=null;await s.refresh()}</script><template><AppShell><PageHeader title="AI Priorities" description="Recommendations stay separate from confirmed tasks until approved"/><div class="mb-4 grid gap-3 sm:grid-cols-3"><StatCard label="Needs review" :value="String(rows.filter(x=>x.status==='suggested'||x.status==='pending').length)" tone="warning"/><StatCard label="Approved" :value="String(rows.filter(x=>x.status==='approved').length)" tone="success"/><StatCard label="Executed" :value="String(rows.filter(x=>x.status==='executed').length)" tone="brand"/></div><div class="grid gap-3 lg:grid-cols-2"><Panel v-for="x in rows" :key="x.id"><div class="p-4"><div class="flex items-start justify-between gap-3"><div><p class="text-sm font-semibold text-content">{{x.title}}</p><p class="mt-1 text-xs leading-5 text-content-secondary">{{x.detail}}</p></div><StatusBadge :status="x.status"/></div><div class="mt-4 flex items-center gap-2"><span class="zs-badge" :class="x.impact==='high'?'badge-danger':x.impact==='medium'?'badge-warning':'badge-neutral'">{{x.impact}} impact</span><span v-if="x.due" class="inline-flex items-center gap-1 text-2xs text-content-muted"><Clock3 class="size-3"/>{{x.due}}</span></div><div v-if="x.status==='suggested'||x.status==='pending'" class="mt-4 flex gap-2"><ZButton @click="ask(x,'approved')"><Check class="size-4"/>Approve</ZButton><ZButton variant="outline" @click="ask(x,'rejected')"><X class="size-4"/>Reject</ZButton></div></div></Panel></div><ConfirmDialog :open="!!target" :title="decision==='approved'?'Approve recommendation?':'Reject recommendation?'" message="This updates the reviewed state only. Execution remains a separate, permission-aware step." :confirm-label="decision==='approved'?'Approve':'Reject'" :tone="decision==='approved'?'brand':'danger'" @cancel="target=null" @confirm="decide"/></AppShell></template>